import { readFileSync } from "node:fs";
import openapiTS, { astToString } from "openapi-typescript";

const contract = new URL(
  "../../specs/001-kanban-ticketing/contracts/openapi.json",
  import.meta.url,
);
const committed = new URL("../src/api/schema.d.ts", import.meta.url);

// The CLI (npm run api:generate) prepends this banner to the output of the programmatic API.
const BANNER =
  "/**\n * This file was auto-generated by openapi-typescript.\n * Do not make direct changes to the file.\n */\n\n";

const generated = BANNER + astToString(await openapiTS(contract));
const current = readFileSync(committed, "utf8");

if (generated !== current) {
  console.error('API types are out of date: run "npm run api:generate"');
  process.exit(1);
}
